        kind:boundedText(file.kind ?? 'original', 'Input kind', 80),
        mediaType:boundedText(file.mediaType ?? 'application/octet-stream', 'Input MIME type', 200),
        ...(file.sha256 ? {sha256:file.sha256} : {})};
