"""Complete saved billing evidence through the existing Operations CLI."""
import base64
import json
from model import Problem, canonical
from operations_commercial_adapter import commercial_store
from operations_billing_evidence import inspect_bundle


def register(command):
    for action in ("catalog", "preview", "save", "show", "compare", "export", "inspect"):
        parser = command("billing-evidence-" + action, "Review original billing evidence without financial changes", case=True, output=True)
        if action in ("show", "compare", "export"):
            parser.add_argument("--review", required=True)
            parser.add_argument("--revision", type=int)
        if action in ("preview", "save", "inspect"):
            parser.add_argument("--file", required=True, help="Complete JSON request, or original ZIP for inspect")
        if action == "export":
            parser.add_argument("--audience", choices=("internal", "customer"), default="internal")


def operate(operations, args, read_bytes, publish):
    if not args.operation.startswith("billing-evidence-"):
        return None
    commercial_store(operations)
    desk = operations.billing_evidence
    action = args.operation.removeprefix("billing-evidence-")
    if action == "catalog":
        result = desk.catalog(args.case)
    elif action in ("preview", "save"):
        try:
            body = json.loads(read_bytes(args.file))
        except (UnicodeError, ValueError) as exc:
            raise Problem("Use the complete original JSON evidence request.", 422, "BILLING_EVIDENCE_INVALID") from exc
        if not isinstance(body, dict):
            raise Problem("Use the complete original JSON evidence request.", 422, "BILLING_EVIDENCE_INVALID")
        result = getattr(desk, action)(args.case, body)
    elif action in ("show", "compare"):
        result = getattr(desk, "get" if action == "show" else "compare")(args.case, args.review, args.revision)
    elif action == "inspect":
        inspected = inspect_bundle(read_bytes(args.file))
        result = {key: value for key, value in inspected.items() if key != "operationsBytes"}
        result["canReceive"] = bool(inspected.get("operationsBytes"))
    elif action == "export":
        if not args.output:
            raise Problem("Choose --output for the complete evidence ZIP.", 422, "OUTPUT_REQUIRED")
        result = desk.export_bundle(args.case, args.review, args.revision, args.audience)
        return {"reviewId": args.review, "revision": args.revision, "audience": args.audience,
                "output": publish(args.output, base64.b64decode(result["contentBase64"], validate=True))}
    else:
        raise Problem("Billing evidence command not found.", 404, "NOT_FOUND")
    return {"output": publish(args.output, canonical(result).encode())} if args.output else result

"""Original Operations routes for frozen customer billing explanations."""
import base64
import binascii
import re
from urllib.parse import parse_qs, unquote
from model import Problem
from operations_commercial_adapter import commercial_store
from operations_billing_evidence import inspect_bundle

CASE = re.compile(r"operation-[a-f0-9]{32}")
REVIEW = re.compile(r"billing-evidence-[a-f0-9]{32}")


def revision(value):
    if value is None:
        return None
    if isinstance(value, bool) or not str(value).isdigit() or not 1 <= int(value) <= 10000000:
        raise Problem("Select an original saved evidence revision.", 422, "BILLING_EVIDENCE_INVALID")
    return int(value)


def handle(handler, parsed, operations, method):
    root = "/api/operations/"
    if not parsed.path.startswith(root):
        return False
    parts = [unquote(item) for item in parsed.path[len(root):].split("/")]
    if len(parts) < 2 or parts[1] != "billing-evidence":
        return False
    if not CASE.fullmatch(parts[0]):
        raise Problem("Billing evidence case not found.", 404, "NOT_FOUND")
    commercial_store(operations)
    desk, case_id, rest = operations.billing_evidence, parts[0], parts[2:]
    query = parse_qs(parsed.query, keep_blank_values=True)
    if any(len(v) != 1 for v in query.values()) or set(query) - {"revision", "audience"}:
        raise Problem("Use one saved revision and one export audience.", 422, "BILLING_EVIDENCE_INVALID")
    selected_revision = revision(query.get("revision", [None])[0])
    if method == "GET":
        if not rest:
            result = desk.catalog(case_id)
        elif len(rest) == 1 and REVIEW.fullmatch(rest[0]):
            result = desk.get(case_id, rest[0], selected_revision)
        elif len(rest) == 2 and REVIEW.fullmatch(rest[0]) and rest[1] == "export.zip":
            audience = query.get("audience", ["internal"])[0]
            if audience not in ("internal", "customer"):
                raise Problem("Choose internal or customer evidence.", 422, "BILLING_EVIDENCE_INVALID")
            result = desk.export_bundle(case_id, rest[0], selected_revision, audience)
            handler.send(200, base64.b64decode(result["contentBase64"], validate=True), result["mediaType"], result["filename"])
            return True
        else:
            raise Problem("Billing evidence page not found.", 404, "NOT_FOUND")
    elif method == "POST":
        body = handler.json_body()
        if rest in (["preview"], ["save"]):
            result = getattr(desk, rest[0])(case_id, body)
        elif len(rest) == 2 and REVIEW.fullmatch(rest[0]) and rest[1] == "compare":
            if not isinstance(body, dict) or set(body) - {"revision"}:
                raise Problem("Select only the saved evidence revision to compare.", 422, "BILLING_EVIDENCE_INVALID")
            result = desk.compare(case_id, rest[0], revision(body.get("revision")))
        elif rest == ["inspect"]:
            if not isinstance(body, dict) or set(body) != {"contentBase64"} or not isinstance(body["contentBase64"], str):
                raise Problem("Supply the complete original evidence ZIP.", 422, "BILLING_EVIDENCE_INVALID")
            try:
                raw = base64.b64decode(body["contentBase64"], validate=True)
            except (ValueError, binascii.Error) as exc:
                raise Problem("The evidence ZIP encoding is invalid.", 422, "BILLING_EVIDENCE_INVALID") from exc
            inspected = inspect_bundle(raw)
            result = {key: value for key, value in inspected.items() if key != "operationsBytes"}
            result["canReceive"] = bool(inspected.get("operationsBytes"))
        else:
            raise Problem("Billing evidence operation not found.", 404, "NOT_FOUND")
    else:
        return False
    handler.send(200, result)
    return True

import {currentStaffContext,staffDeskStorageKey,assertStaffRequestActor} from './staff-session.mjs';
const SCHEMA='sf47.billing-evidence-desk.v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>structuredClone(v),enc=encodeURIComponent;
const today=()=>new Date().toISOString().slice(0,10);
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function styles(){if(document.querySelector('link[data-billing-evidence-style]'))return;const l=document.createElement('link');l.rel='stylesheet';l.href='/operations_billing_evidence.css';l.dataset.billingEvidenceStyle='true';document.head.append(l);}
const plain=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
function readable(value,depth=0){
  if(value===null||value===undefined)return '<span>—</span>';
  if(typeof value!=='object')return '<span>'+esc(value)+'</span>';
  if(depth>7)return '<pre>'+esc(JSON.stringify(value,null,2))+'</pre>';
  if(Array.isArray(value))return value.length?'<ol>'+value.map(v=>'<li>'+readable(v,depth+1)+'</li>').join('')+'</ol>':'<p>None recorded.</p>';
  return '<dl>'+Object.entries(value).map(([key,v])=>'<dt>'+esc(key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/_/g,' '))+'</dt><dd>'+readable(v,depth+1)+'</dd>').join('')+'</dl>';
}
export function mountBillingEvidence({container,current,api,saveApi=api,session={},mutationId,recordingActor,staffContext=currentStaffContext(),isCurrent=()=>true,onSources=()=>{}}){
  styles();
  const context=staffContext?{...staffContext}:null;
  const storageKey=staffDeskStorageKey('sf47.billing-evidence.'+current.program.id,context);
  if(!session.loaded){try{Object.assign(session,JSON.parse(sessionStorage.getItem(storageKey)||'{}'));}catch{}session.loaded=true;}
  session.inputs||={};session.items||={};session.history||=[];session.pending??=null;session.reviewId??=null;session.expectedRevision??=0;
  const root=document.createElement('section');root.className='billing-evidence';root.setAttribute('aria-label','Billing evidence');container.replaceChildren(root);
  const path='/api/operations/'+enc(current.program.id)+'/billing-evidence';
  const state={catalog:null,preview:null,previewRequest:null,saved:null,comparison:null,inspected:null,busy:false,message:'',error:false};
  let active=true,hostBusy=false;
  const visible=()=>active&&root.isConnected&&isCurrent();
  const input=(name,fallback='')=>session.inputs[name]??fallback;
  function actorValue(){try{return typeof recordingActor==='function'?recordingActor():recordingActor||context?.actor||'';}catch{return context?.actor||'';}}
  const button=(label,action,disabled=false,attrs='')=>'<button type="button" data-be-action="'+action+'"'+(disabled?' data-fixed="true" disabled':'')+' '+attrs+'>'+esc(label)+'</button>';
  function field(name,label,fallback='',type='text',help=''){
    return '<label class="be-field"><span>'+esc(label)+'</span>'+(type==='textarea'?'<textarea name="'+esc(name)+'" rows="3">'+esc(input(name,fallback))+'</textarea>':'<input name="'+esc(name)+'" type="'+type+'" value="'+esc(input(name,fallback))+'">')+(help?'<small>'+esc(help)+'</small>':'')+'</label>';
  }
  function persist(required=false){try{const raw=JSON.stringify(session);sessionStorage.setItem(storageKey,raw);if(sessionStorage.getItem(storageKey)!==raw)throw Error('Stored desk differs.');}catch(e){if(required)throw Error('Retain the complete desk before sending its save request: '+e.message);}}
